   114  UA_StatusCode
   115  UA_Client_Subscriptions_addMonitoredEvent(UA_Client *client, const UA_UInt32 subscriptionId,
   116                                           const UA_NodeId nodeId, const UA_UInt32 attributeID,
   117                                           UA_SimpleAttributeOperand *selectClause,
   118                                           const size_t nSelectClauses,
   119                                           UA_ContentFilterElement *whereClause,
   120                                           const size_t nWhereClauses,
   121                                           const UA_MonitoredEventHandlingFunction hf,
   122                                           void *hfContext, UA_UInt32 *newMonitoredItemId) {
   123      UA_Client_Subscription *sub = findSubscription(client, subscriptionId);
   124      if(!sub)
   125          return UA_STATUSCODE_BADSUBSCRIPTIONIDINVALID;
   126
   127      /* Send the request */
   128      UA_CreateMonitoredItemsRequest request;
   129      UA_CreateMonitoredItemsRequest_init(&request);
   130      request.subscriptionId = subscriptionId;
   131
   132      UA_MonitoredItemCreateRequest item;
   133      UA_MonitoredItemCreateRequest_init(&item);
   134      item.itemToMonitor.nodeId = nodeId;
   135      item.itemToMonitor.attributeId = attributeID;
   136      item.monitoringMode = UA_MONITORINGMODE_REPORTING;
   137      item.requestedParameters.clientHandle = ++(client->monitoredItemHandles);
   138      item.requestedParameters.samplingInterval = 0;
   139      item.requestedParameters.discardOldest = false;
   140
   141      UA_EventFilter *evFilter = UA_EventFilter_new();
   142      if(!evFilter) {
   143          return UA_STATUSCODE_BADOUTOFMEMORY;
   144      }
   145      UA_EventFilter_init(evFilter);
   146      evFilter->selectClausesSize = nSelectClauses;
   147      evFilter->selectClauses = selectClause;
   148      evFilter->whereClause.elementsSize = nWhereClauses;
   149      evFilter->whereClause.elements = whereClause;
   150
   151      item.requestedParameters.filter.encoding = UA_EXTENSIONOBJECT_DECODED_NODELETE;
   152      item.requestedParameters.filter.content.decoded.type = &UA_TYPES[UA_TYPES_EVENTFILTER];
   153      item.requestedParameters.filter.content.decoded.data = evFilter;
   154
   155      request.itemsToCreate = &item;
   156      request.itemsToCreateSize = 1;
   157      UA_CreateMonitoredItemsResponse response = UA_Client_Service_createMonitoredItems(client, request);
   158
   159      // slight misuse of retval here to check if the deletion was successfull.
   160      UA_StatusCode retval;
   161      if(response.resultsSize == 0)
   162          retval = response.responseHeader.serviceResult;
   163      else
   164          retval = response.results[0].statusCode;
   165      if(retval != UA_STATUSCODE_GOOD) {
   166          UA_CreateMonitoredItemsResponse_deleteMembers(&response);
   167          UA_EventFilter_delete(evFilter);
   168          return retval;
   169      }
